$("[data-clear-avatar]").addEventListener("click", () => { state.branding.avatar = null; setImagePreview($("[data-avatar-preview]"), null, "🦆"); settingsForm.brandingAvatar.value = ""; markBrandingQueued("Avatar will be removed."); });
$("[data-clear-banner]").addEventListener("click", () => { state.branding.banner = null; setImagePreview($("[data-banner-preview]"), null, "Server banner"); settingsForm.brandingBanner.value = ""; markBrandingQueued("Banner will be removed."); });
$("[data-save-branding]").addEventListener("click", async (event) => { const button = event.currentTarget; button.disabled = true; button.textContent = "Applying…"; const output = $("[data-branding-state]"); try { const body = { nickname: settingsForm.brandingNickname.value.trim() || null, bio: settingsForm.brandingBio.value.trim() || null }; if (state.branding.avatar !== undefined) body.avatar = state.branding.avatar; if (state.branding.banner !== undefined) body.banner = state.branding.banner; await api(`api/guilds/${state.activeGuild.id}/branding`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); state.branding = { avatar: undefined, banner: undefined }; settingsForm.brandingAvatar.value = ""; settingsForm.brandingBanner.value = ""; output.textContent = "Server profile updated on Discord."; output.classList.remove("is-error"); } catch (error) { output.textContent = error.message; output.classList.add("is-error"); } finally { button.disabled = false; button.textContent = "Apply server profile"; } });
$("[data-settings-form]").addEventListener("submit", async (event) => {
  event.preventDefault(); const form = event.currentTarget; const submit = form.querySelector('[type="submit"]'); submit.disabled = true; submit.textContent = "Saving…"; const channelValue = (name) => form[name].value || null;
  try {
    const funSettings = Object.fromEntries(funSettingNames.filter((name) => state.activePlus || !form[name].matches("[data-plus-fun]")).map((name) => [name, form[name].checked]));
    const automationSettings = state.isAdministrator ? {
      automodEnabled: form.automodEnabled.checked, automodHoneypotEnabled: form.automodHoneypotEnabled.checked, automodHoneypotChannelId: channelValue("automodHoneypotChannelId"), automodSwearFilter: form.automodSwearFilter.checked, automodNsfwFilter: form.automodNsfwFilter.checked, automodInviteFilter: form.automodInviteFilter.checked, automodCapsFilter: form.automodCapsFilter.checked, automodMentionLimit: Number(form.automodMentionLimit.value), ...(state.activePlus ? { automodCustomWords: form.automodCustomWords.value.split(",").map((value) => value.trim()).filter(Boolean) } : {}), automodGlobalSlowmodeSeconds: Number(form.automodGlobalSlowmodeSeconds.value), automodChannelSlowmodes: serializeSlowmodes(), automodViolationsBeforeWarn: Number(form.automodViolationsBeforeWarn.value), automodWarningsBeforeAction: Number(form.automodWarningsBeforeAction.value), automodEscalation: form.automodEscalation.value,
      aiScanEnabled: form.aiScanEnabled.checked, aiScanChannelIds: serializeAiScanChannels(), aiScanFlagChannelId: channelValue("aiScanFlagChannelId"), aiScanRulesChannelId: channelValue("aiScanRulesChannelId"), aiScanSensitivity: form.aiScanSensitivity.value,
      reactionRolesEnabled: form.reactionRolesEnabled.checked, reactionRoleChannelId: channelValue("reactionRoleChannelId"), reactionRoleTitle: form.reactionRoleTitle.value, reactionRoleOptions: serializeReactionRoles(), ...(state.activePlus ? { reactionRoleMode: form.reactionRoleMode.value, reactionRoleLimit: Number(form.reactionRoleLimit.value) } : {}),
      ticketsEnabled: form.ticketsEnabled.checked, ticketPanelChannelId: channelValue("ticketPanelChannelId"), ticketCategoryId: form.ticketCategoryId.value || null, ticketSupportRoleId: form.ticketSupportRoleId.value || null, ticketAdminRoleId: form.ticketAdminRoleId.value || null, ticketPanelTitle: form.ticketPanelTitle.value, ticketOptions: serializeTicketOptions(), ...(state.activePlus ? { ticketTranscriptsEnabled: form.ticketTranscriptsEnabled.checked } : {}),
      autorolesEnabled: form.autorolesEnabled.checked, autoroleRoleIds: serializeAutoroles(), levelsEnabled: form.levelsEnabled.checked, levelAnnouncementChannelId: channelValue("levelAnnouncementChannelId"), suggestionsEnabled: form.suggestionsEnabled.checked, suggestionChannelId: channelValue("suggestionChannelId"), starboardEnabled: form.starboardEnabled.checked, starboardChannelId: channelValue("starboardChannelId"), starboardThreshold: Number(form.starboardThreshold.value),
      colorRolesEnabled: form.colorRolesEnabled.checked, colorRoleChannelId: channelValue("colorRoleChannelId"), colorRoleRequiredRoleId: form.colorRoleRequiredRoleId.value || null, colorRoleTitle: form.colorRoleTitle.value, colorRoleDescription: form.colorRoleDescription.value, colorRoleAccent: form.colorRoleAccent.value, colorRoleAllowRemove: form.colorRoleAllowRemove.checked, colorRoleOptions: serializeColorRoles(),
      ...(state.activePlus ? { levelRewards: serializeLevelRewards(), suggestionAnonymousEnabled: form.suggestionAnonymousEnabled.checked, starboardEmoji: form.starboardEmoji.value.trim() || "⭐", starboardColor: form.starboardColor.value, starboardAllowNsfw: form.starboardAllowNsfw.checked, scheduledPosts: serializeScheduledPosts(), colorRoleRandomOnJoin: form.colorRoleRandomOnJoin.checked } : {}),
      customActions: serializeCustomActions()
    } : {};
    await api(`api/guilds/${state.activeGuild.id}/settings`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ aiChatEnabled: form.aiChatEnabled.checked, aiVisionEnabled: form.aiVisionEnabled.checked, aiModel: form.aiModel.value, aiChannelMode: form.aiChannelMode.value, aiContextMode: form.aiContextMode.value, aiResponseStyle: form.aiResponseStyle.value, ...(state.activePlus ? { aiPersonality: form.aiPersonality.value } : {}), ttsEnabled: form.ttsEnabled.checked, ttsAnnounceNames: form.ttsAnnounceNames.checked, ttsModel: form.ttsModel.value, capabilityMode: form.capabilityMode.value, commandPrefix: form.commandPrefix.value, modChannelId: channelValue("modChannelId"), welcomeChannelId: channelValue("welcomeChannelId"), welcomeMessage: form.welcomeMessage.value, farewellMessage: form.farewellMessage.value, logChannelId: channelValue("logChannelId"), ...automationSettings, ...funSettings }) });
    const saveState = $("[data-save-state]"); saveState.textContent = "Saved just now."; saveState.classList.remove("is-error");
  } catch (error) { const saveState = $("[data-save-state]"); saveState.textContent = error.message; saveState.classList.add("is-error"); } finally { submit.disabled = false; submit.textContent = "Save changes"; }
});
$("[data-upgrade-month]").addEventListener("click", () => startCheckout("month")); $("[data-upgrade-year]").addEventListener("click", () => startCheckout("year")); $("[data-manage-billing]").addEventListener("click", manageBilling); $("[data-cancel-subscription]").addEventListener("click", cancelSubscription);
initialize();
